   118→                    type: CONST.PAYMENT_METHODS.PERSONAL_BANK_ACCOUNT,
   119→                };
   120→            } else if (accountType === CONST.PAYMENT_METHODS.DEBIT_CARD) {
   121→                formattedSelectedPaymentMethod = {
   122→                    title: accountData?.addressName ?? '',
   123→                    icon,
   124→                    description: description ?? getPaymentMethodDescription(accountType, accountData, translate),
   125→                    type: CONST.PAYMENT_METHODS.DEBIT_CARD,
   126→                };
   127→            }
