   137→
   138→    const onBankAccountRowPressed = ({accountData}: PaymentMethodPressHandlerParams) => {
   139→        const accountPolicyID = accountData?.additionalData?.policyID;
   140→
   141→        if (accountPolicyID) {
   142→            if (isAccountLocked) {
   143→                showLockedAccountModal();
   144→                return;
   145→            }
   146→            navigateToBankAccountRoute(accountPolicyID, ROUTES.SETTINGS_WALLET);
   147→        }
   148→    };
   149→
   150→    const assignedCardPressed = ({event, cardData, icon, cardID}: CardPressHandlerParams) => {
   151→        paymentMethodButtonRef.current = event?.currentTarget as HTMLDivElement;
   152→        setPaymentMethod({
   153→            isSelectedPaymentMethodDefault: false,
   154→            selectedPaymentMethod: {},
   155→            formattedSelectedPaymentMethod: {
   156→                title: maskCardNumber(cardData?.cardName, cardData?.bank),
   157→                description: cardData ? getDescriptionForPolicyDomainCard(cardData.domainName) : '',
   158→                icon,
   159→            },
   160→            selectedPaymentMethodType: '',
   161→            methodID: cardID ?? CONST.DEFAULT_NUMBER_ID,
   162→        });
   163→    };
   164→
   165→    const addBankAccountPressed = () => {
   166→        if (isAccountLocked) {
   167→            showLockedAccountModal();
   168→            return;
   169→        }
   170→        openPersonalBankAccountSetupView({});
   171→    };
   172→
   173→    const makeDefaultPaymentMethod = useCallback(() => {
   174→        const paymentCardList = fundList ?? {};
   175→        // Find the previous default payment method so we can revert if the MakeDefaultPaymentMethod command errors
   176→        const paymentMethods = formatPaymentMethods(bankAccountList ?? {}, paymentCardList, styles, translate);
   177→
   178→        const previousPaymentMethod = paymentMethods.find((method) => !!method.isDefault);
   179→        const currentPaymentMethod = paymentMethods.find((method) => method.methodID === paymentMethod.methodID);
   180→        if (paymentMethod.selectedPaymentMethodType === CONST.PAYMENT_METHODS.PERSONAL_BANK_ACCOUNT) {
   181→            makeDefaultPaymentMethodPaymentMethods(paymentMethod.selectedPaymentMethod.bankAccountID ?? CONST.DEFAULT_NUMBER_ID, 0, previousPaymentMethod, currentPaymentMethod);
   182→        } else if (paymentMethod.selectedPaymentMethodType === CONST.PAYMENT_METHODS.DEBIT_CARD) {
   183→            makeDefaultPaymentMethodPaymentMethods(0, paymentMethod.selectedPaymentMethod.fundID ?? CONST.DEFAULT_NUMBER_ID, previousPaymentMethod, currentPaymentMethod);
   184→        }
   185→        resetSelectedPaymentMethodData();
   186→    }, [
   187→        fundList,
   188→        bankAccountList,
   189→        styles,
   190→        translate,
   191→        paymentMethod.selectedPaymentMethodType,
   192→        paymentMethod.methodID,
   193→        paymentMethod.selectedPaymentMethod.bankAccountID,
   194→        paymentMethod.selectedPaymentMethod.fundID,
   195→        resetSelectedPaymentMethodData,
   196→    ]);
   197→
   198→    const deletePaymentMethod = useCallback(() => {
   199→        const bankAccountID = paymentMethod.selectedPaymentMethod.bankAccountID;
   200→        const fundID = paymentMethod.selectedPaymentMethod.fundID;
   201→        if (paymentMethod.selectedPaymentMethodType === CONST.PAYMENT_METHODS.PERSONAL_BANK_ACCOUNT && bankAccountID) {
   202→            const bankAccount = bankAccountList?.[paymentMethod.methodID] ?? {};
   203→            deletePaymentBankAccount(bankAccountID, lastUsedPaymentMethods, bankAccount);
   204→        } else if (paymentMethod.selectedPaymentMethodType === CONST.PAYMENT_METHODS.DEBIT_CARD && fundID) {
   205→            deletePaymentCard(fundID);
   206→        }
   207→        setShowConfirmDeleteModal(false);
   208→        resetSelectedPaymentMethodData();
   209→    }, [
   210→        paymentMethod.selectedPaymentMethod.bankAccountID,
   211→        paymentMethod.selectedPaymentMethod.fundID,
   212→        paymentMethod.selectedPaymentMethodType,
   213→        paymentMethod.methodID,
   214→        resetSelectedPaymentMethodData,
   215→        bankAccountList,
   216→        lastUsedPaymentMethods,
   217→    ]);
   218→
   219→    /**
   220→     * Navigate to the appropriate page after completing the KYC flow, depending on what initiated it
   221→     */
   222→    const navigateToWalletOrTransferBalancePage = (source?: Source) => {
   223→        Navigation.navigate(source === CONST.KYC_WALL_SOURCE.ENABLE_WALLET ? ROUTES.SETTINGS_WALLET : ROUTES.SETTINGS_WALLET_TRANSFER_BALANCE);
   224→    };
   225→
   226→    useEffect(() => {
   227→        // If the user was previously offline, skip debouncing showing the loader
   228→        if (!network.isOffline) {
   229→            updateShouldShowLoadingSpinner();
   230→        } else {
   231→            debounceSetShouldShowLoadingSpinner();
   232→        }
   233→    }, [network.isOffline, debounceSetShouldShowLoadingSpinner, updateShouldShowLoadingSpinner]);
   234→
   235→    useEffect(() => {
   236→        if (network.isOffline) {
   237→            return;
   238→        }
   239→        getPaymentMethods(true);
   240→    }, [network.isOffline]);
   241→
   242→    // Don't show "Make default payment method" button if it's the only payment method or if it's already the default
   243→    const isCurrentPaymentMethodDefault = () => {
   244→        const hasMultiplePaymentMethods = formatPaymentMethods(bankAccountList ?? {}, fundList ?? {}, styles, translate).length > 1;
   245→        if (hasMultiplePaymentMethods) {
   246→            if (paymentMethod.formattedSelectedPaymentMethod.type === CONST.PAYMENT_METHODS.PERSONAL_BANK_ACCOUNT) {
   247→                return paymentMethod.selectedPaymentMethod.bankAccountID === userWallet?.walletLinkedAccountID;
   248→            }
   249→            if (paymentMethod.formattedSelectedPaymentMethod.type === CONST.PAYMENT_METHODS.DEBIT_CARD) {
   250→                return paymentMethod.selectedPaymentMethod.fundID === userWallet?.walletLinkedAccountID;
   251→            }
   252→        }
   253→        return true;
   254→    };
   255→
   256→    const shouldShowMakeDefaultButton =
   257→        !isCurrentPaymentMethodDefault() &&
   258→        !(
   259→            paymentMethod.formattedSelectedPaymentMethod.type === CONST.PAYMENT_METHODS.PERSONAL_BANK_ACCOUNT && paymentMethod.selectedPaymentMethod.type === CONST.BANK_ACCOUNT.TYPE.BUSINESS
   260→        ) &&
   261→        paymentMethod.selectedPaymentMethod?.state === CONST.BANK_ACCOUNT.STATE.OPEN;
   262→
   263→    const shouldShowEnableGlobalReimbursementsButton =
   264→        paymentMethod.selectedPaymentMethod?.additionalData?.currency === CONST.CURRENCY.USD &&
   265→        paymentMethod.selectedPaymentMethod.type === CONST.BANK_ACCOUNT.TYPE.BUSINESS &&
   266→        !paymentMethod.selectedPaymentMethod?.additionalData?.corpay?.achAuthorizationForm &&
   267→        paymentMethod.selectedPaymentMethod?.state === CONST.BANK_ACCOUNT.STATE.OPEN;
   268→
   269→    // Determines whether or not the modal popup is mounted from the bottom of the screen instead of the side mount on Web or Desktop screens
   270→    const alertTextStyle = [styles.inlineSystemMessage, styles.flexShrink1];
   271→    const alertViewStyle = [styles.flexRow, styles.alignItemsCenter, styles.w100];
   272→    const headerWithBackButton = (
   273→        <HeaderWithBackButton
   274→            title={translate('common.wallet')}
   275→            icon={illustrations.MoneyIntoWallet}
   276→            shouldUseHeadlineHeader
   277→            shouldShowBackButton={shouldUseNarrowLayout}
   278→            shouldDisplaySearchRouter
   279→            onBackButtonPress={Navigation.popToSidebar}
   280→        />
   281→    );
   282→
   283→    const bottomMountItem = useMemo(
   284→        () => ({
   285→            text: paymentMethod.formattedSelectedPaymentMethod.title,
   286→            icon: paymentMethod.formattedSelectedPaymentMethod.icon?.icon,
   287→            iconHeight: paymentMethod.formattedSelectedPaymentMethod.icon?.iconHeight ?? paymentMethod.formattedSelectedPaymentMethod.icon?.iconSize,
   288→            iconWidth: paymentMethod.formattedSelectedPaymentMethod.icon?.iconWidth ?? paymentMethod.formattedSelectedPaymentMethod.icon?.iconSize,
   289→            iconStyles: paymentMethod.formattedSelectedPaymentMethod.icon?.iconStyles,
   290→            description: paymentMethod.formattedSelectedPaymentMethod.description,
   291→            wrapperStyle: [styles.mb4, styles.ph5, styles.pt3],
   292→            interactive: false,
   293→            displayInDefaultIconColor: true,
   294→        }),
   295→        [paymentMethod.formattedSelectedPaymentMethod, styles.mb4, styles.ph5, styles.pt3],
   296→    );
   297→
   298→    const threeDotMenuItems = useMemo(
   299→        () => [
   300→            ...(shouldUseNarrowLayout ? [bottomMountItem] : []),
   301→            ...(shouldShowMakeDefaultButton
   302→                ? [
   303→                      {
   304→                          text: translate('walletPage.setDefaultConfirmation'),
   305→                          icon: icons.Star,
   306→                          onSelected: () => {
   307→                              if (isAccountLocked) {
   308→                                  closeModal(() => showLockedAccountModal());
   309→                                  return;
   310→                              }
   311→                              makeDefaultPaymentMethod();
   312→                          },
   313→                          numberOfLinesTitle: 0,
   314→                      },
   315→                  ]
   316→                : []),
   317→            {
   318→                text: translate('common.delete'),
   319→                icon: icons.Trashcan,
   320→                onSelected: () => {
   321→                    if (isAccountLocked) {
   322→                        closeModal(() => showLockedAccountModal());
   323→                        return;
   324→                    }
   325→                    closeModal(() => setShowConfirmDeleteModal(true));
   326→                },
   327→            },
   328→            ...(shouldShowEnableGlobalReimbursementsButton
   329→                ? [
   330→                      {
   331→                          text: translate('common.enableGlobalReimbursements'),
   332→                          icon: icons.Globe,
   333→                          onSelected: () => {
   334→                              if (isAccountLocked) {
   335→                                  closeModal(() => showLockedAccountModal());
   336→                                  return;
   337→                              }
   338→                              closeModal(() => Navigation.navigate(ROUTES.SETTINGS_WALLET_ENABLE_GLOBAL_REIMBURSEMENTS.getRoute(paymentMethod.selectedPaymentMethod.bankAccountID)));
   339→                          },
   340→                      },
   341→                  ]
   342→                : []),
   343→        ],
   344→        [
   345→            icons,
   346→            shouldUseNarrowLayout,
   347→            bottomMountItem,
   348→            shouldShowMakeDefaultButton,
   349→            translate,
   350→            shouldShowEnableGlobalReimbursementsButton,
   351→            isAccountLocked,
   352→            makeDefaultPaymentMethod,
   353→            showLockedAccountModal,
   354→            paymentMethod.selectedPaymentMethod.bankAccountID,
   355→        ],
   356→    );
   357→
   358→    const cardThreeDotsMenuItems = useMemo(
   359→        () => [
   360→            ...(shouldUseNarrowLayout ? [bottomMountItem] : []),
   361→            {
   362→                text: translate('workspace.common.viewTransactions'),
   363→                icon: icons.MoneySearch,
   364→                onSelected: () => {
   365→                    Navigation.navigate(
   366→                        ROUTES.SEARCH_ROOT.getRoute({
   367→                            query: buildCannedSearchQuery({
   368→                                type: CONST.SEARCH.DATA_TYPES.EXPENSE,
   369→                                status: CONST.SEARCH.STATUS.EXPENSE.ALL,
   370→                                cardID: String(paymentMethod.methodID),
   371→                            }),
   372→                        }),
   373→                    );
   374→                },
   375→            },
   376→        ],
   377→        [bottomMountItem, icons.MoneySearch, paymentMethod.methodID, shouldUseNarrowLayout, translate],
   378→    );
   379→
   380→    if (isLoadingApp) {
   381→        return (
   382→            <ScreenWrapper
   383→                testID={WalletPage.displayName}
   384→                shouldShowOfflineIndicatorInWideScreen
   385→            >
   386→                {headerWithBackButton}
   387→                <View style={styles.flex1}>
   388→                    <FullScreenLoadingIndicator />
   389→                </View>
   390→            </ScreenWrapper>
   391→        );
   392→    }
   393→
   394→    return (
   395→        <ScreenWrapper
   396→            testID={WalletPage.displayName}
   397→            shouldShowOfflineIndicatorInWideScreen
   398→        >
   399→            {headerWithBackButton}
   400→            <ScrollView style={styles.pt3}>
   401→                <View style={[styles.flex1, shouldUseNarrowLayout ? styles.workspaceSectionMobile : styles.workspaceSection]}>
   402→                    <OfflineWithFeedback
   403→                        style={styles.flex1}
   404→                        contentContainerStyle={styles.flex1}
   405→                        onClose={clearWalletError}
   406→                        errors={userWallet?.errors}
   407→                        errorRowStyles={styles.ph6}
   408→                    >
   409→                        <Section
   410→                            subtitle={translate('walletPage.addBankAccountToSendAndReceive')}
   411→                            title={translate('common.bankAccounts')}
   412→                            isCentralPane
   413→                            subtitleMuted
   414→                            titleStyles={styles.accountSettingsSectionTitle}
   415→                            illustrationContainerStyle={styles.cardSectionIllustrationContainer}
   416→                            illustrationBackgroundColor="#411103"
   417→                            // eslint-disable-next-line react/jsx-props-no-spreading
   418→                            {...walletIllustration}
   419→                        >
   420→                            <PaymentMethodList
   421→                                onPress={onBankAccountRowPressed}
   422→                                onAddBankAccountPress={addBankAccountPressed}
   423→                                onThreeDotsMenuPress={paymentMethodPressed}
   424→                                style={[styles.mt5, [shouldUseNarrowLayout ? styles.mhn5 : styles.mhn8]]}
   425→                                listItemStyle={shouldUseNarrowLayout ? styles.ph5 : styles.ph8}
   426→                                shouldShowBankAccountSections
   427→                                threeDotsMenuItems={threeDotMenuItems}
   428→                            />
   429→                        </Section>
   430→
   431→                        {hasAssignedCard ? (
   432→                            <Section
   433→                                subtitle={translate('walletPage.assignedCardsDescription')}
   434→                                title={translate('walletPage.assignedCards')}
   435→                                isCentralPane
   436→                                subtitleMuted
   437→                                titleStyles={styles.accountSettingsSectionTitle}
   438→                            >
   439→                                <PaymentMethodList
   440→                                    shouldShowAddBankAccount={false}
   441→                                    shouldShowAssignedCards
   442→                                    onPress={assignedCardPressed}
   443→                                    threeDotsMenuItems={cardThreeDotsMenuItems}
   444→                                    style={[styles.mt5, [shouldUseNarrowLayout ? styles.mhn5 : styles.mhn8]]}
   445→                                    listItemStyle={shouldUseNarrowLayout ? styles.ph5 : styles.ph8}
   446→                                />
   447→                            </Section>
   448→                        ) : null}
   449→
   450→                        {hasWallet && (
   451→                            <Section
   452→                                subtitle={translate(`walletPage.sendAndReceiveMoney`)}
   453→                                title={translate('walletPage.expensifyWallet')}
   454→                                isCentralPane
   455→                                subtitleMuted
   456→                                titleStyles={styles.accountSettingsSectionTitle}
   457→                                childrenStyles={shouldShowLoadingSpinner ? styles.mt7 : styles.mt5}
   458→                            >
   459→                                <>
   460→                                    {shouldShowLoadingSpinner && (
   461→                                        <ActivityIndicator
   462→                                            size={CONST.ACTIVITY_INDICATOR_SIZE.LARGE}
   463→                                            style={[styles.mb5]}
   464→                                        />
   465→                                    )}
   466→                                    {!shouldShowLoadingSpinner && hasActivatedWallet && (
   467→                                        <OfflineWithFeedback
   468→                                            pendingAction={CONST.RED_BRICK_ROAD_PENDING_ACTION.ADD}
   469→                                            errors={walletTerms?.errors}
   470→                                            onClose={clearWalletTermsError}
   471→                                            errorRowStyles={[styles.ml10, styles.mr2]}
   472→                                            style={[styles.mb2]}
   473→                                        >
   474→                                            <MenuItemWithTopDescription
   475→                                                description={translate('walletPage.balance')}
   476→                                                title={convertToDisplayString(userWallet?.currentBalance ?? 0)}
   477→                                                titleStyle={styles.textHeadlineH2}
   478→                                                interactive={false}
   479→                                                wrapperStyle={styles.sectionMenuItemTopDescription}
   480→                                                copyValue={convertToDisplayString(userWallet?.currentBalance ?? 0)}
   481→                                                copyable
   482→                                            />
   483→                                        </OfflineWithFeedback>
   484→                                    )}
   485→
   486→                                    <KYCWall
   487→                                        ref={kycWallRef}
   488→                                        onSuccessfulKYC={(_iouPaymentType?: PaymentMethodType, source?: Source) => navigateToWalletOrTransferBalancePage(source)}
   489→                                        onSelectPaymentMethod={(selectedPaymentMethod: string) => {
   490→                                            if (hasActivatedWallet || selectedPaymentMethod !== CONST.PAYMENT_METHODS.PERSONAL_BANK_ACCOUNT) {
   491→                                                return;
   492→                                            }
   493→                                            // To allow upgrading to a gold wallet, continue with the KYC flow after adding a bank account
   494→                                            setPersonalBankAccountContinueKYCOnSuccess(ROUTES.SETTINGS_WALLET);
   495→                                        }}
   496→                                        enablePaymentsRoute={ROUTES.SETTINGS_ENABLE_PAYMENTS}
   497→                                        addDebitCardRoute={ROUTES.SETTINGS_ADD_DEBIT_CARD}
   498→                                        source={hasActivatedWallet ? CONST.KYC_WALL_SOURCE.TRANSFER_BALANCE : CONST.KYC_WALL_SOURCE.ENABLE_WALLET}
   499→                                        shouldIncludeDebitCard={hasActivatedWallet}
   500→                                    >
   501→                                        {(triggerKYCFlow, buttonRef: RefObject<View | null>) => {
   502→                                            if (shouldShowLoadingSpinner) {
   503→                                                return null;
   504→                                            }
   505→
   506→                                            if (hasActivatedWallet) {
   507→                                                return (
   508→                                                    <MenuItem
   509→                                                        ref={buttonRef as ForwardedRef<View>}
   510→                                                        title={translate('common.transferBalance')}
   511→                                                        icon={icons.Transfer}
   512→                                                        onPress={(event) => {
   513→                                                            triggerKYCFlow({event});
   514→                                                        }}
   515→                                                        shouldShowRightIcon
   516→                                                        wrapperStyle={[
   517→                                                            styles.transferBalance,
   518→                                                            shouldUseNarrowLayout ? styles.mhn5 : styles.mhn8,
   519→                                                            shouldUseNarrowLayout ? styles.ph5 : styles.ph8,
   520→                                                        ]}
   521→                                                    />
   522→                                                );
   523→                                            }
   524→
   525→                                            if (isPendingOnfidoResult) {
   526→                                                return (
   527→                                                    <View style={alertViewStyle}>
   528→                                                        <Icon
   529→                                                            src={icons.Hourglass}
   530→                                                            fill={theme.icon}
   531→                                                        />
   532→
   533→                                                        <Text style={alertTextStyle}>{translate('walletPage.walletActivationPending')}</Text>
   534→                                                    </View>
   535→                                                );
   536→                                            }
   537→
   538→                                            if (hasFailedOnfido) {
   539→                                                return (
   540→                                                    <View style={alertViewStyle}>
   541→                                                        <Icon
   542→                                                            src={icons.Exclamation}
   543→                                                            fill={theme.icon}
   544→                                                        />
   545→
   546→                                                        <Text style={alertTextStyle}>{translate('walletPage.walletActivationFailed')}</Text>
   547→                                                    </View>
   548→                                                );
   549→                                            }
   550→
   551→                                            return (
   552→                                                <MenuItem
   553→                                                    title={translate('walletPage.enableWallet')}
   554→                                                    icon={icons.Wallet}
   555→                                                    ref={buttonRef as ForwardedRef<View>}
   556→                                                    onPress={() => {
   557→                                                        if (isAccountLocked) {
   558→                                                            showLockedAccountModal();
   559→                                                            return;
   560→                                                        }
   561→
   562→                                                        if (!isUserValidated) {
   563→                                                            Navigation.navigate(ROUTES.SETTINGS_WALLET_VERIFY_ACCOUNT);
   564→                                                            return;
   565→                                                        }
   566→                                                        Navigation.navigate(ROUTES.SETTINGS_ENABLE_PAYMENTS);
   567→                                                    }}
   568→                                                    wrapperStyle={[
   569→                                                        styles.transferBalance,
   570→                                                        shouldUseNarrowLayout ? styles.mhn5 : styles.mhn8,
   571→                                                        shouldUseNarrowLayout ? styles.ph5 : styles.ph8,
   572→                                                    ]}
   573→                                                />
   574→                                            );
   575→                                        }}
   576→                                    </KYCWall>
   577→                                </>
   578→                            </Section>
   579→                        )}
   580→                    </OfflineWithFeedback>
   581→                </View>
   582→            </ScrollView>
   583→            <ConfirmModal
   584→                isVisible={showConfirmDeleteModal}
   585→                onConfirm={deletePaymentMethod}
   586→                onCancel={() => setShowConfirmDeleteModal(false)}
   587→                title={translate('walletPage.deleteAccount')}
   588→                prompt={translate('walletPage.deleteConfirmation')}
   589→                confirmText={translate('common.delete')}
   590→                cancelText={translate('common.cancel')}
   591→                shouldShowCancelButton
   592→                danger
   593→                onModalHide={resetSelectedPaymentMethodData}
   594→            />
   595→        </ScreenWrapper>
   596→    );
   597→}
   598→
   599→WalletPage.displayName = 'WalletPage';
   600→
   601→export default WalletPage;
   602→

